// ---- lib/match.js
// Choix automatique du produit. Collé tel quel en tête des nodes Code n8n (voir scripts/bundle.mjs).
const ACCESSORY_RE = /sleeve|pochette|sticker|autocollant|\bkit\b|feuille de score|piste de suivi|figurine|\bsacs?\b|insert|organiseur|playmat|tapis de jeu|goodies/i;

// Accents combinants (plage U+0300 a U+036F) : construits sans echappement unicode, que n8n transforme a l enregistrement.
const COMBINING_RE = new RegExp('[' + String.fromCharCode(0x300) + '-' + String.fromCharCode(0x36f) + ']', 'g');

function normalize(s) {
  return String(s || '')
    .normalize('NFD').replace(COMBINING_RE, '')
    .toLowerCase()
    .replace(/\((vf|vo|fr|en|version francaise|version anglaise)\)/g, ' ')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function isAccessory(title) {
  return ACCESSORY_RE.test(title || '');
}

// Vrai si a et b sont égaux à une insertion, suppression ou substitution près.
function within1(a, b) {
  if (a === b) return true;
  if (Math.abs(a.length - b.length) > 1) return false;
  let i = 0;
  while (i < a.length && i < b.length && a[i] === b[i]) i++;
  if (a.length === b.length) return a.slice(i + 1) === b.slice(i + 1);
  return a.length > b.length ? a.slice(i + 1) === b.slice(i) : b.slice(i + 1) === a.slice(i);
}

// Ordre de préférence : titre exact → titre à une lettre près (« catane » → « Catan ») →
// titres contenant tous les mots, jeu de base avant extension, dans l'ordre de pertinence du site.
function pickProduct(query, candidates) {
  const q = normalize(query);
  const pool = (candidates || []).filter(c => c && c.title && !isAccessory(c.title));
  if (!q || pool.length === 0) return null;
  const frFirst = (a, b) => (a.lang === 'fr' ? 0 : 1) - (b.lang === 'fr' ? 0 : 1);
  const exact = pool.filter(c => normalize(c.title) === q).sort(frFirst);
  if (exact.length) return exact[0];
  if (q.length >= 5) {
    const near = pool.filter(c => within1(normalize(c.title), q)).sort(frFirst);
    if (near.length) return near[0];
  }
  const words = q.split(' ');
  const all = pool.filter(c => { const t = ` ${normalize(c.title)} `; return words.every(w => t.includes(` ${w} `)); });
  const isExt = c => /\bext(ension)?\b/.test(normalize(c.title));
  const base = /\bext(ension)?\b/.test(q) ? all : all.filter(c => !isExt(c));
  return [...(base.length ? base : all)].sort(frFirst)[0] || null;
}

if (typeof module !== 'undefined' && module.exports) module.exports = { normalize, isAccessory, pickProduct };


// ---- lib/sites.js
// Parseurs des pages de recherche (structure observée le 2026-10-13, voir docs/sources.md).
// Pas de `URL` dans le bac à sable des nodes Code n8n (vérifié le 2026-10-13) : résolution à la main.
function absUrl(base, href) {
  const h = String(href || '').trim();
  if (!h) return null;
  if (/^https?:\/\//i.test(h)) return h;
  if (h.startsWith('//')) return 'https:' + h;
  const origin = (String(base).match(/^https?:\/\/[^/]+/i) || [])[0];
  if (!origin) return null;
  return origin + (h.startsWith('/') ? h : '/' + h);
}

function clean(s) {
  return String(s || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#0?39;|&#x27;|&apos;/g, "'").replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ').trim();
}

// Philibert : une carte = <div class="product-card … " data-pid="…">, titre dans a.product-card__title,
// langue dans span.product-card__feature, note « x/5 » avant le titre si le produit a des avis.
function parsePhilibertSearch(html) {
  const out = [];
  for (const card of String(html || '').split(/(?=<div\s+class="product-card\s[^"]*"\s+data-pid=)/).slice(1)) {
    const a = card.match(/<a class="h6 mb-0 product-card__title[^"]*" href="([^"]+)">([^<]+)<\/a>/);
    if (!a) continue;
    const features = [...card.matchAll(/<span class="product-card__feature">([^<]*)<\/span>/g)].map(m => clean(m[1]));
    const lang = features.includes('Français') ? 'fr' : features.includes('Anglais') ? 'en' : undefined;
    const n = clean(card.slice(0, a.index)).match(/(\d(?:[.,]\d)?)\/5/);
    out.push({
      title: clean(a[2]),
      url: absUrl('https://www.philibertnet.com/', a[1]),
      lang,
      note: n ? parseFloat(n[1].replace(',', '.')) : null,
    });
  }
  return out;
}

// Esprit Jeu : <h3 class="bp_designation"><a href="…"> Titre </a></h3>
function parseEspritJeuSearch(html) {
  return [...String(html || '').matchAll(/<h3 class="bp_designation">\s*<a href="([^"]+)">\s*([^<]*?)\s*<\/a>/g)]
    .map(m => ({ title: clean(m[2]), url: absUrl('https://www.espritjeu.com/', m[1]) }))
    .filter(c => c.title && c.url);
}

// Okkazeo : un résultat = <article class="… jeu …"> avec <h4 class="titre"><a href="/jeux/<id>/<slug>">Titre</a></h4>
// et <b>N annonces</b> (nombre d'annonces de cette édition ; null si absent).
function parseOkkazeoSearch(html) {
  const out = [];
  for (const art of String(html || '').split(/(?=<article class="grid-x box_article jeu)/).slice(1)) {
    const a = art.match(/<h4 class="titre"><a href="(\/jeux\/\d+\/[^"]*)"[^>]*>([^<]*)<\/a>/);
    if (!a) continue;
    const n = art.match(/<b>\s*(\d+)\s+annonces?\s*<\/b>/);
    const c = { title: clean(a[2]), url: absUrl('https://www.okkazeo.com/', a[1]), annonces: n ? Number(n[1]) : null };
    if (c.title && c.url) out.push(c);
  }
  return out;
}

if (typeof module !== 'undefined' && module.exports) module.exports = { parsePhilibertSearch, parseEspritJeuSearch, parseOkkazeoSearch };


// ---- lib/panier.js
// Matchmaking Okkazeo : quels vendeurs proposent plusieurs des jeux d'une liste ? (node « Panier », voir scripts/bundle.mjs)
// Une annonce de la fiche d'un jeu = <article class="text-left jeu …"> : lien /annonces/<id>/<slug>, prix, « Vendu par <b>pseudo</b> »,
// « Ville (CP)<br/> », pastille « sticker envoi » si le vendeur expédie (structure observée le 2026-10-13).
const nettoie = t => String(t || '').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#0?39;|&apos;/g, "'").replace(/\s+/g, ' ').trim();

function parseAnnoncesArticles(html) {
  const out = [];
  for (const art of String(html || '').split(/(?=<article class="text-left jeu)/).slice(1)) {
    const vendeur = (art.match(/Vendu par\s*<b>([^<]+)<\/b>/) || [])[1];
    const prix = art.match(/<span class="prix">\s*(\d+)\s*€\s*<span class="sub">\s*(\d{2})/);
    if (!vendeur || !prix) continue;
    const lien = (art.match(/href="(\/annonces\/\d+[^"]*)"/) || [])[1];
    const loc = art.match(/([^<>\n]+?)\s*\((\d{4,5})\)\s*<br/);
    // « Jeu d'occasion (état correct) », « Jeu d'occasion + extensions (état excellent) », « (juste déballé) », « Jeu neuf ».
    const etat = /Jeu\s+neuf/i.test(art) ? 'neuf'
      : ((art.match(/\(état ([^)]+)\)/) || art.match(/Jeu\s+d'occasion[^(<]*\(([^)]+)\)/) || [])[1] || '');
    out.push({
      vendeur: nettoie(vendeur),
      prix: Number(prix[1]) + Number(prix[2]) / 100,
      url: lien ? 'https://www.okkazeo.com' + lien : null,
      ville: loc ? nettoie(loc[1]) : null,
      cp: loc ? loc[2] : null,
      etat: etat ? nettoie(etat) : null,
      envoi: /class="sticker envoi"/.test(art), // « Envoi en France », « Envoi France et Europe »
    });
  }
  return out;
}

// jeux : [{ titre, annonces: [...] }] (une entrée par jeu demandé et trouvé). Vendeurs qui ont au moins 2 jeux différents,
// avec l'annonce la moins chère de chaque jeu. Tri : nombre de jeux, puis vendeur près de Paris (cps), puis total le plus bas.
function matchVendeurs(jeux, cps, n = 10) {
  const proches = new Set(cps || []);
  const vendeurs = new Map();
  for (const j of jeux || []) {
    for (const a of j.annonces || []) {
      const k = String(a.vendeur || '').trim().toLowerCase();
      if (!k) continue;
      const v = vendeurs.get(k) || { vendeur: a.vendeur, ville: a.ville, cp: a.cp, jeux: new Map() };
      const prev = v.jeux.get(j.titre);
      if (!prev || a.prix < prev.prix) v.jeux.set(j.titre, { jeu: j.titre, ...a });
      if (!v.cp && a.cp) { v.ville = a.ville; v.cp = a.cp; }
      vendeurs.set(k, v);
    }
  }
  return [...vendeurs.values()]
    .filter(v => v.jeux.size >= 2)
    .map(v => {
      const annonces = [...v.jeux.values()].sort((a, b) => a.prix - b.prix);
      return {
        vendeur: v.vendeur, ville: v.ville, cp: v.cp,
        procheParis: !!(v.cp && proches.has(v.cp)),
        envoi: annonces.every(a => a.envoi),
        nbJeux: annonces.length,
        total: Math.round(annonces.reduce((s, a) => s + a.prix, 0) * 100) / 100,
        annonces: annonces.map(a => ({ jeu: a.jeu, prix: a.prix, etat: a.etat, url: a.url })),
      };
    })
    .sort((a, b) => b.nbJeux - a.nbJeux || Number(b.procheParis) - Number(a.procheParis) || a.total - b.total)
    .slice(0, n);
}

// « Clank, Abyss » ou une liste par ligne → noms uniques (8 au plus : chaque jeu coûte 2 à 4 requêtes Okkazeo).
function parseListeJeux(brut, max = 8) {
  const vus = new Set();
  return String(brut || '').split(/[|\n;,]+/).map(s => s.trim()).filter(s => {
    const k = s.toLowerCase();
    if (!s || vus.has(k)) return false;
    vus.add(k);
    return true;
  }).slice(0, max);
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { parseAnnoncesArticles, matchVendeurs, parseListeJeux };
}


const CP_PARIS = ["75001","75002","75003","75004","75005","75006","75007","75008","75009","75010","75011","75012","75013","75014","75015","75016","75017","75018","75019","75020","75116","92100","92110","92120","92130","92140","92160","92170","92200","92220","92240","92260","92290","92300","92320","92330","92340","92350","93100","93130","93170","93230","93260","93300","93310","93400","93500","94000","94100","94110","94120","94130","94140","94150","94160","94200","94210","94220","94230","94240","94250","94260","94270","94300","94310","94320","94340","94400","94410","94550","94600","94700","94800"];

// ---- n8n/code/panier.body.js
// Matchmaking Okkazeo : GET ?jeux=Clank|Abyss|… → vendeurs qui proposent au moins 2 de ces jeux (voir lib/panier.js).
const noms = parseListeJeux($('Webhook').first().json.query.jeux);
if (noms.length < 2) return [{ json: { jeux: noms.map(demande => ({ demande, titre: null, url: null, annonces: 0 })), vendeurs: [], erreurs: ['au moins 2 jeux'] } }];

// Okkazeo refuse (403) le User-Agent seul : il faut les en-têtes d'un vrai navigateur (mêmes en-têtes que le node Sources).
const BROWSER = {
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0 Safari/537.36',
  'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
  'Accept-Language': 'fr-FR,fr;q=0.9',
  'Sec-Fetch-Dest': 'document', 'Sec-Fetch-Mode': 'navigate', 'Sec-Fetch-Site': 'none', 'Sec-Fetch-User': '?1',
  'Upgrade-Insecure-Requests': '1',
  'sec-ch-ua': '"Chromium";v="130", "Google Chrome";v="130", "Not?A_Brand";v="99"',
  'sec-ch-ua-mobile': '?0', 'sec-ch-ua-platform': '"Windows"',
  'Accept-Encoding': 'gzip, deflate, br', 'Referer': 'https://www.google.com/',
};
const get = async url => {
  const r = await this.helpers.httpRequest({ url, headers: BROWSER, json: false, timeout: 10000, returnFullResponse: true, ignoreHttpStatusErrors: true });
  if (r.statusCode >= 400) throw new Error(`HTTP ${r.statusCode} ${url}`);
  return String(r.body ?? '');
};

// Un jeu : recherche Okkazeo (titre exact), puis les annonces de ses éditions qui en ont (3 au plus, comme le node Sources).
async function unJeu(nom) {
  const recherche = 'https://www.okkazeo.com/jeux/resultats?rech_nom=' + encodeURIComponent(nom);
  const search = await get(recherche);
  if (!/Nous avons trouvé|Aucun jeu ne correspond/.test(search)) throw new Error('page de recherche inattendue');
  const cands = parseOkkazeoSearch(search);
  const p = pickProduct(nom, cands);
  if (!p) return { demande: nom, titre: null, url: recherche, annonces: [] };
  const editions = cands.filter(c => normalize(c.title) === normalize(p.title) && c.annonces !== 0).slice(0, 3);
  const pages = await Promise.all(editions.map(e => get(e.url)));
  return { demande: nom, titre: p.title, url: editions.length === 1 ? editions[0].url : recherche, annonces: pages.flatMap(parseAnnoncesArticles) };
}

// 3 jeux à la fois pour ne pas inonder Okkazeo.
const res = [];
for (let i = 0; i < noms.length; i += 3) res.push(...await Promise.allSettled(noms.slice(i, i + 3).map(unJeu)));
const msg = r => (r.reason && r.reason.message) || String(r.reason);
const jeux = res.map((r, i) => (r.status === 'fulfilled' ? r.value : { demande: noms[i], titre: null, url: null, annonces: [], erreur: msg(r) }));
const vendeurs = matchVendeurs(jeux.filter(j => j.titre), CP_PARIS);
const erreurs = jeux.filter(j => j.erreur).map(j => `${j.demande}: ${j.erreur}`);
return [{ json: { jeux: jeux.map(j => ({ demande: j.demande, titre: j.titre, url: j.url, annonces: j.annonces.length })), vendeurs, erreurs } }];
